<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { ComboboxChipState, setComboboxChipContext } from './combobox-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; value: unknown; ref?: HTMLSpanElement | null; } let { children, value, ref = $bindable(null), ...rest }: Props = $props(); const chip = setComboboxChipContext(new ComboboxChipState()); $effect.pre(() => { chip.value = value; });</script><span bind:this={ref} {...rest} data-value={String(value)}>{@render children?.()}</span>
